unsafe delegate int* D1(int* ptr);
unsafe delegate int*[] D2(int*[] a);
unsafe delegate delegate*<void> D3(delegate*<void> ptr);
unsafe delegate C<delegate*<void>[]> D4(C<delegate*<void>[]> a);

class D
{
    public static D1 M1()
    {
        return (ptr) => ptr; // 1
    }
    public static D2 M2()
    {
        return (a) => a; // 2
    }
    public static D3 M3()
    {
        return (ptr) => ptr; // 3
    }
    public static D4 M4()
    {
        return (a) => a; // 4
    }
}

